(* [comment removed for export] *)
(* [comment removed for export] *)
Definition gct_post (ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (T : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 T) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 16, bv_unsigned sp)] m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' (bv_unsigned sp - 16) (bv_unsigned sp).
Lemma gct_spec : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (ctx T : Z),
  mem_inv bsegs m -> tp = Z_to_bv 64 ATP ->
  rw_cells bsegs m ATSD_CELL [C1 (b8 1)] -> rw_cells bsegs m (ATSD_CELL + 4) [C4 (wz 0)] ->
  rw_cells bsegs m AMUSL_TSD [C8 (wz 0x682b98)] ->
  rw_cells bsegs m ATSD0 [C8 (wz ctx)] -> rw_cells bsegs m (ctx + 152) [C8 (wz T)] ->
  0 < ctx -> ctx + 160 <= aceil ->
  stk bsegs m (bv_unsigned sp - 16) (bv_unsigned sp) -> aceil <= bv_unsigned sp - 16 ->
  evt bsegs (gct_post ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc T m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
