(* [comment removed for export] *)
(* [comment removed for export] *)
Definition dtls_post (ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 a5 a6 a7 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 144, bv_unsigned sp)] m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' (bv_unsigned sp - 144) (bv_unsigned sp).
Lemma dtls_spec : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (D : Z),
  mem_inv bsegs m -> tp = Z_to_bv 64 ATP -> a0 = Z_to_bv 64 AGOT_FSTLS ->
  rw_cells bsegs m AGOT_FSTLS [C8 (wz 1); C8 (wz 0xfffffffffffff800)] ->
  rw_cells bsegs m AGOT_CFLAGS [C8 (wz 0x1bf2e8)] -> rw_cells bsegs m ACF_ITLS_CELL [C1 (b8 1)] ->
  rw_cells bsegs m AGOT_VERBOSITY [C8 (wz AVERBOSITY_CELL)] -> rw_cells bsegs m AVERBOSITY_CELL [C4 (wz 0)] ->
  rw_cells bsegs m AGOT_DTLS [C8 (wz 0x8)] ->
  rw_cells bsegs m (ATP + 8) [C8 (wz D)] -> rw_cells bsegs m (D + 24) [C8 (wz ATP)] ->
  0 < D -> D + 32 <= aceil ->
  stk bsegs m (bv_unsigned sp - 144) (bv_unsigned sp) -> aceil <= bv_unsigned sp - 144 ->
  evt bsegs (dtls_post ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
