    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo : Z),
  mem_inv bsegs m -> tp = Z_to_bv 64 ATP -> a0 = Z_to_bv 64 AGOT_FSTLS ->
  ACONST m -> athr_cells m ->
  stk bsegs m lo (bv_unsigned sp) -> aceil <= lo -> lo <= bv_unsigned sp - 176 ->
  evt bsegs (tls_icpt_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
